struct runtime_binding_copy_t {
    player_input_t row;

    __forceinline void copy_from(const player_input_config_t *source)
    {
        row.move_key_forward = source->move_key_forward;
        row.move_key_backward = source->move_key_backward;
        row.turn_key_left = source->turn_key_left;
        row.turn_key_right = source->turn_key_right;
        row.fire_key = source->fire_key;
        row.key_reserved_0 = source->key_reserved_0;
        row.key_reserved_1 = source->key_reserved_1;
        row.aim_key_left = source->aim_key_left;
        row.aim_key_right = source->aim_key_right;
        row.axis_aim_y = source->axis_aim_y;
        row.axis_aim_x = source->axis_aim_x;
        row.axis_move_y = source->axis_move_y;
        row.axis_move_x = source->axis_move_x;
    }

    __forceinline void operator=(const player_input_config_t &source)
    {
        copy_from(&source);
    }
};

