        runtime->move_key_forward = row.move_key_forward;
        runtime->move_key_backward = row.move_key_backward;
        runtime->turn_key_left = row.turn_key_left;
        runtime->turn_key_right = row.turn_key_right;
        runtime->fire_key = row.fire_key;
        runtime->key_reserved_0 = row.key_reserved_0;
        runtime->key_reserved_1 = row.key_reserved_1;
        runtime->aim_key_left = row.aim_key_left;
        runtime->aim_key_right = row.aim_key_right;
        runtime->axis_aim_y = row.axis_aim_y;
        runtime->axis_aim_x = row.axis_aim_x;
        runtime->axis_move_y = row.axis_move_y;
